CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('superadmin','admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS articles (id INTEGER PRIMARY KEY AUTOINCREMENT, section TEXT NOT NULL CHECK (section IN ('kemahasiswaan','eksternal','berita')), title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL, body TEXT NOT NULL, image_url TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','inactive')), author_id INTEGER NOT NULL REFERENCES users(id), published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_articles_section_status ON articles(section,status,created_at DESC);
